import typing

from ..transport.frames import Ack, Chunk, Frame, Nack
from . import exc as jsi_exc


class TransferStateMachine:
    """State machine for validating frames that are sent/received during data
    transfer of a single message."""

    def __init__(self):
        self._current_state = self._st_initial
        self._current_chunk = None
        self._bytes_left = None
        self._exc = None

    @property
    def current_chunk(self) -> Chunk:
        """Reference to current chunk."""
        return self._current_chunk

    @property
    def bytes_left(self) -> int:
        """Number of bytes left to be transferred.

        This must be 0 for completed transfers.
        """
        return self._bytes_left

    @property
    def size(self) -> int:
        """Size of transferred data."""
        return self._current_chunk.message_size

    def is_done(self) -> bool:
        """Check if transfer is done (i.e. completed, rejected or failed)."""
        return self.is_completed() or\
            self.is_failed() or\
            self.is_rejected()

    def is_completed(self) -> bool:
        """Check if transfer is completed."""
        return self._current_state == self._st_completed

    def is_failed(self) -> bool:
        """Check if transfer is failed."""
        return self._current_state == self._st_failed

    def is_rejected(self) -> bool:
        """Check if transfer is rejected."""
        return self._current_state == self._st_rejected

    def dispatch(self, frame: Frame):
        """Dispatch frame to the state machine and perform state traversal.

        If *frame* is not allowed in current state, then raise
        :exc:`ProtocolError` exception.
        """
        next_state = self._current_state(frame)
        if next_state is None:
            raise RuntimeError(
                f"no state traversal defined for state {self._current_state.__qualname__} and frame {frame.type}"
            )
        self._current_state = next_state

    def _set_and_raise_protocol_error(self, frame: Frame, message: str):
        self._exc = jsi_exc.ProtocolError(message)
        self._current_state = self._st_failed
        self._current_state(frame)

    def _set_and_raise_transfer_rejected_error(self, frame: Nack):
        self._exc = jsi_exc.TransferRejectedError()
        self._current_state = self._st_rejected
        self._current_state(frame)

    def _st_initial(self, frame: Frame):
        if frame.type != Frame.Type.CHUNK:
            self._set_and_raise_protocol_error(frame, f"expected CHUNK frame, got {frame.type.name} frame instead")
        return self._st_first_chunk(frame)

    def _st_failed(self, frame: Frame):
        raise self._exc

    def _st_rejected(self, frame: Frame):
        raise self._exc

    def _st_completed(self, frame: Frame):
        pass

    def _st_first_chunk(self, frame: Chunk):
        self._current_chunk = frame
        self._bytes_left = frame.message_size
        return self._st_ack_nack

    def _st_next_chunk(self, frame: Chunk):
        if frame.type != Frame.Type.CHUNK:
            self._set_and_raise_protocol_error(frame, f"expected CHUNK frame, got {frame.type.name} frame instead")
        current_chunk = self._current_chunk
        if current_chunk.index + 1 != frame.index:
            self._set_and_raise_protocol_error(
                frame, f"got CHUNK with invalid 'index': {frame.index} (given) != {current_chunk.index + 1} (expected)"
            )
        if current_chunk.message_size != frame.message_size:
            self._set_and_raise_protocol_error(
                frame,
                f"got CHUNK with invalid 'message_size': {frame.message_size} (given) != {current_chunk.message_size} (expected)"
            )
        if len(frame.payload) > self._bytes_left:
            self._set_and_raise_protocol_error(
                frame,
                f"got final CHUNK with too large payload: {len(frame.payload)} bytes (given) != {self._bytes_left} bytes (expected)"
            )
        self._current_chunk = frame
        return self._st_ack_nack

    def _st_ack_nack(self, frame: typing.Union[Ack, Nack]):
        if frame.type not in (Frame.Type.ACK, Frame.Type.NACK):
            self._set_and_raise_protocol_error(
                frame, f"expected ACK or NACK frame, got {frame.type.name} frame instead"
            )
        if self._current_chunk.key != frame.key:
            self._set_and_raise_protocol_error(
                frame,
                f"got {frame.type.name} with unexpected 'key': {frame.key} (given) != {self._current_chunk.key} (expected)"
            )
        if frame.type == Frame.Type.NACK:
            self._set_and_raise_transfer_rejected_error(frame)
        self._bytes_left -= len(self._current_chunk.payload)
        if self._bytes_left > 0:
            return self._st_next_chunk
        return self._st_completed
